import{_t as e,it as t,n,rt as r}from"./chunks/framework.D2cFUyj2.js";var i=JSON.parse(`{"title":"검색 기록","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. 검색 기록 (Search History)","slug":"_1-검색-기록-search-history","link":"#_1-검색-기록-search-history","children":[]},{"level":2,"title":"2. 키워드 기록 (Keyword History)","slug":"_2-키워드-기록-keyword-history","link":"#_2-키워드-기록-keyword-history","children":[]},{"level":2,"title":"3. 검색어 연결 (Query Associations)","slug":"_3-검색어-연결-query-associations","link":"#_3-검색어-연결-query-associations","children":[]}],"relativePath":"ko-KR/user-guide/settings/history.md","filePath":"ko-KR/user-guide/settings/history.md","lastUpdated":1792776074000}`),a={name:`ko-KR/user-guide/settings/history.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="검색-기록" tabindex="-1">검색 기록 <a class="header-anchor" href="#검색-기록" aria-label="Permalink to “검색 기록”">​</a></h1><p>기록 설정 페이지에서는 경로별 사용 빈도, 입력한 검색어, 확인된 검색어 연결을 <strong>검색 기록</strong>·<strong>키워드 기록</strong>·<strong>검색어 연결</strong>의 3개 독립 탭에서 관리합니다.</p><h2 id="_1-검색-기록-search-history" tabindex="-1">1. 검색 기록 (Search History) <a class="header-anchor" href="#_1-검색-기록-search-history" aria-label="Permalink to “1. 검색 기록 (Search History)”">​</a></h2><p>실제로 실행한 파일, 폴더, 앱의 실행 빈도와 최근 시간을 기록하여 비슷한 관련성을 가진 직접 일치 결과 사이의 순서를 정교하게 조정합니다.</p><ul><li><strong>감쇠 빈도 기반 미세 정렬</strong>: 자주 여는 항목은 90일 반감기 점수로 <strong>동일한 일치 등급 안에서</strong> 우선 정렬되며, 정확한 직접 이름 일치를 앞지르지 않습니다.</li><li><strong>인라인 윈도우 스마트 분류</strong>: 파일 대화상자의 인라인 검색 시 현재 열린 폴더 내부 항목은 &quot;현재 폴더&quot;, 나머지는 &quot;전체 검색&quot;으로 분류됩니다.</li><li><strong>삭제된 경로 자동 필터링</strong>: 이동되거나 삭제된 경로는 결과에서 자동 제외됩니다.</li><li><strong>관리 기능</strong>: <ul><li><strong>기록 기능 활성화</strong>, 검색 필터링, <strong>N회 이하 기록 지우기</strong>, 개별 삭제 및 <strong>모든 기록 삭제</strong>, 실시간 횟수 갱신을 지원합니다.</li></ul></li></ul><h2 id="_2-키워드-기록-keyword-history" tabindex="-1">2. 키워드 기록 (Keyword History) <a class="header-anchor" href="#_2-키워드-기록-keyword-history" aria-label="Permalink to “2. 키워드 기록 (Keyword History)”">​</a></h2><p>결과나 액션을 실행했거나 해당 검색어로 메인 윈도우를 열 때 실제로 사용한 <strong>원시 검색 문자열 자체</strong>를 기억합니다.</p><ul><li><strong>단축키 빠른 탐색</strong>: 퀵 검색창에서 <strong><code>Alt+Up</code></strong>(이전) / <strong><code>Alt+Down</code></strong>(다음)으로 과거 검색어를 탐색하고 <strong><code>Ctrl+Delete</code></strong>로 즉시 삭제할 수 있습니다.</li><li><strong>독립 관리</strong>: 전용 활성화 스위치, 필터링, <strong>N회 이하 기록 지우기</strong>, 개별 삭제 및 <strong>모든 기록 삭제</strong>를 제공합니다.</li></ul><h2 id="_3-검색어-연결-query-associations" tabindex="-1">3. 검색어 연결 (Query Associations) <a class="header-anchor" href="#_3-검색어-연결-query-associations" aria-label="Permalink to “3. 검색어 연결 (Query Associations)”">​</a></h2><p>경로별 일반 사용 빈도와 분리하여 확인된 <strong>검색어 → 대상 경로</strong> 연결을 저장합니다.</p><ul><li><strong>3회 직접 실행 임계값</strong>: 정규화된 동일 검색어에서 <strong>3회 이상</strong> 직접 선택해 실행한 항목만 보조 후보로 재호출되어 일회성 오클릭 오염을 방지합니다.</li><li><strong>자가 강화 루프 차단</strong>: 학습된 보조 결과에서 다시 실행해도 미확인 횟수가 부풀려지지 않으며 항상 직접 일치 뒤에 배치됩니다.</li><li><strong>독립 정리</strong>: 경로별 사용 빈도를 유지한 채 개별 연결 삭제 또는 전체 초기화를 수행할 수 있습니다.</li></ul>`,11)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};